 old=Path(reg['roles'][r['arm']]['source_route_run']);oldm=read(old/'manifest.json');oldp=read(old/'independent_audit.json')['physical_metrics'];new=b/'runs'/r['arm'];line=next(l for l in reversed((new/'stdout.log').read_text().splitlines()) if ROW.match(l));match=ROW.match(line);last=dict(iteration=int(match[1]),rerouted_nets=int(match[2]),rerouted_connections=int(match[3]),overused_rr_nodes=int(match[4]));rows.append(dict(**r,last_iteration=last,original_count2_resources=dict(wirelength=oldp['planar_wirelength_excluding_sb_half_nodes'],SB_pairs=oldp['sb_pairs_used'],CB_sources=oldp['cb_crossing_output_sources_used']),resource_delta_from_original_count2=dict(wirelength=r['wirelength']-oldp['planar_wirelength_excluding_sb_half_nodes'],SB_pairs=r['SB_pairs']-oldp['sb_pairs_used'],CB_sources=r['CB_sources']-oldp['cb_crossing_output_sources_used']),actual_legal_opportunities=len(r['native_legal_iterations']),configured_max_convergences=8,observed_stop_condition='configured_max_convergences' if len(r['native_legal_iterations'])==8 else 'no_connections_rerouted_matches_native_stop_branch' if last['rerouted_connections']==0 else 'not_disambiguated',original_count2_whole_route_seconds=oldm['wall_seconds'],qualification='Recorded old/new complete times are single observations with different convergence parameters, not rotated statistical speedup. Printed first-legal iteration values match, but intermediate complete route equivalence was not checked.'))
